        return f"Calculator(history_length={len(self._history)}, memory={mem_str})"

    def evaluate(self, expression: str) -> float:
        """Parses and evaluates math expressions using standard precedence via Shunting-yard."""
        ops = {
            '+': (1, self._add),
            '-': (1, self._subtract),
            '*': (2, self._multiply),
            '/': (2, self._divide),
            '%': (2, self._modulo),
            '^': (3, self._power)
        }

        start_idx = len(self._history)

