                    output_stack.append(float(token))
                elif token == '-':
                    # Detect unary minus
                    if i == 0 or tokens[i-1] == '(':
                        output_stack.append(-1.0)
                        operator_stack.append('*')
                    else:
                        while operator_stack and operator_stack[-1] in ops and ops[operator_stack[-1]][0] >= ops[token][0]:
                            self._apply_internal_op(operator_stack, output_stack, ops)
                        operator_stack.append(token)
                elif token in ops:
                    while operator_stack and operator_stack[-1] in ops and ops[operator_stack[-1]][0] >= ops[token][0]:
                        self._apply_internal_op(operator_stack, output_stack, ops)
                    operator_stack.append(token)
                elif token == '(':
