                        self._apply_internal_op(operator_stack, output_stack, ops)
                    operator_stack.pop()

            while operator_stack:
                self._apply_internal_op(operator_stack, output_stack, ops)

            result = output_stack[0]
            return result
        finally:
            self._history = self._history[:start_idx]
            self._record("evaluate", res=float(output_stack[0] if output_stack else 0.0), expr=expression)

    def _apply_internal_op(self, operator_stack: List[str], output_stack: List[float], ops: Dict[str, Tuple[int, Callable[[float, float], float]]]) -> None:
        """Executes one operation using internal math methods."""
        op_symbol = operator_stack.pop()
        b = output_stack.pop()
        a = output_stack.pop()
        result = ops[op_symbol][1](a, b)
        output_stack.append(result)

